        public static string Get(string directory, string filename, string extension)
        {
            string value;
            if (Map.TryGetValue(directory + "/" + filename + "." + extension, out value))
                return value;
            if (Map.TryGetValue(directory + "/" + filename, out value))
                return value;
            return null;
        }
